/* Lot 100: the reader colour (wf_cssprop_color): names, hex, rgb(), hsl(), hwb(), color-mix() (generated by scripts/lot100_colorgen.py; expectations from scripts/lot100_colormodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[160];

static int syn(const char *s) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(s, (int)strlen(s), &g_p);
    return g_p.syntax != 0;
}

/* the reader colour of v[0..n) as "#rrggbb alpha", "-" when it is not one */
static const char *rcn(const char *v, int n) {
    unsigned int c = 0xdeadbeefu;
    int a = -7, r = wf_cssprop_color(v, n, &c, &a);
    if (!r) return c == 0xdeadbeefu && a == -7 ? "-" : "WRITTEN";
    if (r != 1 || c > 0xffffffu || a < 0 || a > 255) return "BAD CODE";
    snprintf(g_o, sizeof(g_o), "#%06x %d", c, a);
    return g_o;
}

static const char *rc(const char *v) { return rcn(v, (int)strlen(v)); }

